SET ROLE __OWNER__;
CREATE TABLE ai_review_v4.applications(id uuid PRIMARY KEY REFERENCES ai_review_v4.requests(id),command_id uuid NOT NULL UNIQUE,business_key text NOT NULL UNIQUE,request_hash text NOT NULL,outcome_digest text NOT NULL,status text NOT NULL CHECK(status IN('PENDING','APPLYING','APPLIED')),owner uuid,token uuid,fence bigint NOT NULL DEFAULT 0,lease_until timestamptz,available_at timestamptz NOT NULL DEFAULT clock_timestamp(),result jsonb,error_code text);
CREATE FUNCTION ai_review_v4._application_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP IN('DELETE','TRUNCATE') OR NOT EXISTS(SELECT 1 FROM ai_review_v4._ctx WHERE pid=pg_backend_pid() AND tx=txid_current()) THEN RAISE EXCEPTION 'AI_IMPORT_DIRECT_WRITE';END IF;
 IF TG_OP='UPDATE' THEN IF OLD.status='APPLIED' OR OLD.id<>NEW.id OR OLD.command_id<>NEW.command_id OR OLD.business_key<>NEW.business_key OR OLD.request_hash<>NEW.request_hash OR OLD.outcome_digest<>NEW.outcome_digest OR NEW.fence<OLD.fence THEN RAISE EXCEPTION 'AI_IMPORT_APPLICATION_IMMUTABLE';END IF;END IF;RETURN NEW;
END $$;
CREATE TRIGGER ai_import_application_write BEFORE INSERT OR UPDATE OR DELETE ON ai_review_v4.applications FOR EACH ROW EXECUTE FUNCTION ai_review_v4._application_guard();
CREATE TRIGGER ai_import_application_truncate BEFORE TRUNCATE ON ai_review_v4.applications FOR EACH STATEMENT EXECUTE FUNCTION ai_review_v4._application_guard();
ALTER TABLE ai_review_v4.applications ENABLE ALWAYS TRIGGER ai_import_application_write;ALTER TABLE ai_review_v4.applications ENABLE ALWAYS TRIGGER ai_import_application_truncate;
CREATE FUNCTION ai_review_v4._application_view(wanted uuid) RETURNS jsonb LANGUAGE sql STABLE AS $$ SELECT jsonb_build_object('requestId',id,'header',(SELECT r.header FROM ai_review_v4.requests r WHERE r.id=a.id),'commandId',command_id,'businessKey',business_key,'requestHash',request_hash,'outcomeDigest',outcome_digest,'status',status,'owner',owner,'token',token,'fence',fence::text,'leaseUntil',lease_until,'result',result,'errorCode',error_code) FROM ai_review_v4.applications a WHERE a.id=wanted $$;
CREATE FUNCTION ai_review_v4.record_import_result_v4(wanted uuid,owner uuid,token uuid,fence bigint,sealed jsonb,digest text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ai_review_v4,governance_jobs_v4,state_map_v1,pg_temp AS $$
DECLARE h jsonb;i jsonb;tenant text;seed text;cmd uuid;key text;req text;BEGIN
 PERFORM pg_advisory_xact_lock_shared(1229213011,1);PERFORM pg_advisory_xact_lock_shared(1229213011,2);PERFORM ai_review_v4._assert();SELECT header INTO STRICT h FROM ai_review_v4.requests WHERE id=wanted;tenant:=h->>'tenantId';
 i:=(governance_jobs_v4._state(tenant,'blob','ai_import_intent:'||(h->>'objectId')))->'value';IF i->>'format' IS DISTINCT FROM 'IDMS_AI_IMPORT_INTENT_V4_1' OR i->'header' IS DISTINCT FROM h THEN RAISE EXCEPTION 'AI_IMPORT_RESULT_INTENT';END IF;
 PERFORM ai_review_v4.result_v4(wanted,owner,token,fence,sealed,digest);
 seed:=encode(sha256(convert_to('["ai-import-apply","'||wanted::text||'","'||digest||'"]','UTF8')),'hex');cmd:=(substr(seed,1,8)||'-'||substr(seed,9,4)||'-'||substr(seed,13,4)||'-'||substr(seed,17,4)||'-'||substr(seed,21,12))::uuid;
 key:=encode(sha256(convert_to('["'||tenant||'","idms.ai-import-v4","SYSTEM","'||cmd::text||'"]','UTF8')),'hex');
 req:=encode(sha256(convert_to('{"action":"AI_IMPORT_APPLY","id":"'||(h->>'objectId')||'","input":{"outcomeDigest":"'||digest||'","requestId":"'||wanted::text||'"}}','UTF8')),'hex');
 INSERT INTO ai_review_v4._ctx VALUES(pg_backend_pid(),txid_current());INSERT INTO ai_review_v4.applications(id,command_id,business_key,request_hash,outcome_digest,status) VALUES(wanted,cmd,key,req,digest,'PENDING');DELETE FROM ai_review_v4._ctx WHERE pid=pg_backend_pid();
END $$;
CREATE FUNCTION ai_review_v4.read_application_v4(wanted uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ai_review_v4,pg_temp AS $$ BEGIN PERFORM ai_review_v4._assert();RETURN ai_review_v4._application_view(wanted);END $$;
CREATE FUNCTION ai_review_v4.claim_application_v4(owner uuid,token uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ai_review_v4,pg_temp AS $$ DECLARE a ai_review_v4.applications;BEGIN
 PERFORM ai_review_v4._assert();IF owner IS NULL OR token IS NULL THEN RAISE EXCEPTION 'AI_IMPORT_INPUT';END IF;
 SELECT * INTO a FROM ai_review_v4.applications q WHERE q.status<>'APPLIED' AND q.available_at<=clock_timestamp() AND (q.status<>'APPLYING' OR q.lease_until<=clock_timestamp()) ORDER BY q.available_at,q.id FOR UPDATE SKIP LOCKED LIMIT 1;IF NOT FOUND THEN RETURN NULL;END IF;
 INSERT INTO ai_review_v4._ctx VALUES(pg_backend_pid(),txid_current());UPDATE ai_review_v4.applications SET status='APPLYING',owner=claim_application_v4.owner,token=claim_application_v4.token,fence=fence+1,lease_until=clock_timestamp()+interval '30 seconds',error_code=NULL WHERE id=a.id;DELETE FROM ai_review_v4._ctx WHERE pid=pg_backend_pid();RETURN ai_review_v4._application_view(a.id);
END $$;
CREATE FUNCTION ai_review_v4._application_lease(wanted uuid,owner uuid,token uuid,fence bigint) RETURNS ai_review_v4.applications LANGUAGE plpgsql AS $$ DECLARE a ai_review_v4.applications;BEGIN SELECT * INTO a FROM ai_review_v4.applications q WHERE id=wanted FOR UPDATE;IF NOT FOUND OR a.status<>'APPLYING' OR a.owner IS DISTINCT FROM owner OR a.token IS DISTINCT FROM token OR a.fence IS DISTINCT FROM fence OR a.lease_until<=clock_timestamp() THEN RAISE EXCEPTION 'AI_IMPORT_APPLICATION_LEASE_LOST';END IF;RETURN a;END $$;
CREATE FUNCTION ai_review_v4.check_application_v4(wanted uuid,owner uuid,token uuid,fence bigint) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ai_review_v4,pg_temp AS $$ BEGIN PERFORM ai_review_v4._assert();PERFORM ai_review_v4._application_lease(wanted,owner,token,fence);RETURN ai_review_v4._application_view(wanted);END $$;
CREATE FUNCTION ai_review_v4.renew_application_v4(wanted uuid,owner uuid,token uuid,fence bigint) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ai_review_v4,pg_temp AS $$ BEGIN PERFORM ai_review_v4._assert();PERFORM ai_review_v4._application_lease(wanted,owner,token,fence);INSERT INTO ai_review_v4._ctx VALUES(pg_backend_pid(),txid_current());UPDATE ai_review_v4.applications SET lease_until=clock_timestamp()+interval '30 seconds' WHERE id=wanted;DELETE FROM ai_review_v4._ctx WHERE pid=pg_backend_pid();RETURN true;END $$;
CREATE FUNCTION ai_review_v4.defer_application_v4(wanted uuid,owner uuid,token uuid,fence bigint,code text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ai_review_v4,pg_temp AS $$ BEGIN PERFORM ai_review_v4._assert();PERFORM ai_review_v4._application_lease(wanted,owner,token,fence);IF code IS NULL OR code NOT IN('BUSINESS_BUSY','TENANT_NOT_ACTIVE','POLICY_CHANGED','APPLICATION_UNCONFIRMED') THEN RAISE EXCEPTION 'AI_IMPORT_INPUT';END IF;INSERT INTO ai_review_v4._ctx VALUES(pg_backend_pid(),txid_current());UPDATE ai_review_v4.applications SET status='PENDING',owner=NULL,token=NULL,lease_until=NULL,available_at=clock_timestamp()+interval '3 seconds',error_code=code WHERE id=wanted;DELETE FROM ai_review_v4._ctx WHERE pid=pg_backend_pid();END $$;
CREATE FUNCTION ai_review_v4.prepare_application_v4(tenant text,wanted uuid,owner uuid,token uuid,fence bigint,command uuid,revision bigint,root bytea,operations jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ai_review_v4,governance_jobs_v4,state_map_v1,pg_temp AS $$ DECLARE a ai_review_v4.applications;r jsonb;c jsonb;j jsonb;BEGIN
 PERFORM state_map_v1.read_head_v1(tenant);PERFORM pg_advisory_xact_lock_shared(1229213011,2);PERFORM ai_review_v4._assert();IF tenant IS DISTINCT FROM (SELECT m.tenant FROM ai_review_v4._meta m) THEN RAISE EXCEPTION 'AI_IMPORT_TENANT';END IF;a:=ai_review_v4._application_lease(wanted,owner,token,fence);
 r:=state_map_v1.apply_delta_v1(tenant,command,revision,root,operations);c:=(governance_jobs_v4._state(tenant,'domain_head','control'))->'value';j:=(governance_jobs_v4._state(tenant,'domain_head','governance_job'))->'value';IF c->>'status'='UPDATING' AND j->>'key' IS DISTINCT FROM a.business_key THEN RAISE EXCEPTION 'AI_IMPORT_OTHER_MAINTENANCE';END IF;RETURN r;
END $$;
CREATE FUNCTION ai_review_v4.publish_application_v4(tenant text,wanted uuid,owner uuid,token uuid,fence bigint,branch uuid,command uuid,base_revision bigint,base_root bytea,stage_revision bigint,stage_root bytea,stage_receipt bytea) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ai_review_v4,governance_jobs_v4,state_map_v1,pg_temp AS $$ DECLARE a ai_review_v4.applications;p jsonb;r jsonb;c jsonb;cat jsonb;j jsonb;BEGIN
 PERFORM state_map_v1.read_head_v1(tenant);PERFORM pg_advisory_xact_lock_shared(1229213011,2);PERFORM ai_review_v4._assert();IF tenant IS DISTINCT FROM (SELECT m.tenant FROM ai_review_v4._meta m) THEN RAISE EXCEPTION 'AI_IMPORT_TENANT';END IF;a:=ai_review_v4._application_lease(wanted,owner,token,fence);
 c:=(governance_jobs_v4._state(tenant,'domain_head','control'))->'value';j:=(governance_jobs_v4._state(tenant,'domain_head','governance_job'))->'value';IF c->>'status' IS DISTINCT FROM 'UPDATING' OR j->>'key' IS DISTINCT FROM a.business_key OR j->>'phase' IS DISTINCT FROM 'PLANNED' THEN RAISE EXCEPTION 'AI_IMPORT_APPLICATION_PLAN';END IF;
 p:=state_map_v1.publish_branch_v1(tenant,branch,command,base_revision,base_root,stage_revision,stage_root,stage_receipt);r:=(governance_jobs_v4._state(tenant,'receipt','governance_command:'||a.business_key))->'value';c:=(governance_jobs_v4._state(tenant,'domain_head','control'))->'value';cat:=(governance_jobs_v4._state(tenant,'domain_head','governance_console'))->'value';
 IF r->>'format' IS DISTINCT FROM 'IDMS_GOVERNANCE_COMMAND_V4_1' OR r->>'key' IS DISTINCT FROM a.business_key OR r->>'requestHash' IS DISTINCT FROM a.request_hash OR r->>'status' IS DISTINCT FROM 'COMMITTED' OR r->>'branchId' IS DISTINCT FROM branch::text OR r->>'publicationId' IS DISTINCT FROM command::text OR r->'result'->>'requestId' IS DISTINCT FROM wanted::text OR r->'result'->>'outcomeDigest' IS DISTINCT FROM a.outcome_digest OR c->>'status' IS DISTINCT FROM 'ACTIVE' OR cat->>'format' IS DISTINCT FROM 'IDMS_GOVERNANCE_CONSOLE_V4_1' OR cat->>'governanceAnchorDigest' IS DISTINCT FROM c->>'governanceAnchorDigest' THEN RAISE EXCEPTION 'AI_IMPORT_APPLICATION_PROOF';END IF;
 INSERT INTO ai_review_v4._ctx VALUES(pg_backend_pid(),txid_current());UPDATE ai_review_v4.applications SET status='APPLIED',result=jsonb_build_object('completion',r,'publication',p),owner=NULL,token=NULL,lease_until=NULL,error_code=NULL WHERE id=wanted;DELETE FROM ai_review_v4._ctx WHERE pid=pg_backend_pid();RETURN jsonb_build_object('publication',p,'application',ai_review_v4._application_view(wanted));
END $$;
CREATE FUNCTION governance_jobs_v4.prepare_ai_console_v4(tenant text,wanted uuid,owner uuid,token uuid,fence bigint,grant_revision bigint,deadline timestamptz,command uuid,revision bigint,root bytea,operations jsonb) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,governance_jobs_v4,pg_temp AS $$ SELECT governance_jobs_v4.prepare_console_v4(tenant,wanted,owner,token,fence,grant_revision,deadline,command,revision,root,operations) $$;
CREATE FUNCTION governance_jobs_v4.publish_ai_console_v4(tenant text,wanted uuid,owner uuid,token uuid,fence bigint,grant_revision bigint,deadline timestamptz,branch uuid,command uuid,base_revision bigint,base_root bytea,stage_revision bigint,stage_root bytea,stage_receipt bytea,header jsonb,header_digest text,sealed jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,governance_jobs_v4,ai_review_v4,pg_temp AS $$ DECLARE v jsonb;i jsonb;r jsonb;BEGIN
 v:=governance_jobs_v4.publish_console_v4(tenant,wanted,owner,token,fence,grant_revision,deadline,branch,command,base_revision,base_root,stage_revision,stage_root,stage_receipt);r:=v->'job'->'result';
 IF v->'job'->>'action'='IMPORT_CREATE' AND r->>'status'='AI_PENDING' THEN
  i:=(governance_jobs_v4._state(tenant,'blob','ai_import_intent:'||(r->>'batchId')))->'value';
  IF i->>'format' IS DISTINCT FROM 'IDMS_AI_IMPORT_INTENT_V4_1' OR i->'header' IS DISTINCT FROM header OR i->>'headerDigest' IS DISTINCT FROM header_digest OR header->>'objectId' IS DISTINCT FROM r->>'batchId' OR header->>'requestId' IS DISTINCT FROM r->>'aiRequestId' OR header->>'snapshotDigest' IS DISTINCT FROM r->>'snapshotDigest' OR header->>'batchVersion' IS DISTINCT FROM r->>'version' THEN RAISE EXCEPTION 'AI_IMPORT_PUBLICATION_INTENT';END IF;
  PERFORM ai_review_v4.enqueue_v4(header,header_digest,sealed);
 ELSIF header IS NOT NULL OR header_digest IS NOT NULL OR sealed IS NOT NULL THEN RAISE EXCEPTION 'AI_IMPORT_UNEXPECTED_ENQUEUE';END IF;RETURN v;
END $$;
REVOKE ALL ON TABLE ai_review_v4.applications FROM PUBLIC,__APP__;
REVOKE ALL ON FUNCTION ai_review_v4._application_guard(),ai_review_v4._application_view(uuid),ai_review_v4._application_lease(uuid,uuid,uuid,bigint),ai_review_v4.record_import_result_v4(uuid,uuid,uuid,bigint,jsonb,text),ai_review_v4.read_application_v4(uuid),ai_review_v4.claim_application_v4(uuid,uuid),ai_review_v4.check_application_v4(uuid,uuid,uuid,bigint),ai_review_v4.renew_application_v4(uuid,uuid,uuid,bigint),ai_review_v4.defer_application_v4(uuid,uuid,uuid,bigint,text),ai_review_v4.prepare_application_v4(text,uuid,uuid,uuid,bigint,uuid,bigint,bytea,jsonb),ai_review_v4.publish_application_v4(text,uuid,uuid,uuid,bigint,uuid,uuid,bigint,bytea,bigint,bytea,bytea),governance_jobs_v4.prepare_ai_console_v4(text,uuid,uuid,uuid,bigint,bigint,timestamptz,uuid,bigint,bytea,jsonb),governance_jobs_v4.publish_ai_console_v4(text,uuid,uuid,uuid,bigint,bigint,timestamptz,uuid,uuid,bigint,bytea,bigint,bytea,bytea,jsonb,text,jsonb) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION ai_review_v4.enqueue_v4(jsonb,text,jsonb),ai_review_v4.result_v4(uuid,uuid,uuid,bigint,jsonb,text),governance_jobs_v4.prepare_console_v4(text,uuid,uuid,uuid,bigint,bigint,timestamptz,uuid,bigint,bytea,jsonb),governance_jobs_v4.publish_console_v4(text,uuid,uuid,uuid,bigint,bigint,timestamptz,uuid,uuid,bigint,bytea,bigint,bytea,bytea) FROM __APP__;
GRANT EXECUTE ON FUNCTION ai_review_v4.record_import_result_v4(uuid,uuid,uuid,bigint,jsonb,text),ai_review_v4.read_application_v4(uuid),ai_review_v4.claim_application_v4(uuid,uuid),ai_review_v4.check_application_v4(uuid,uuid,uuid,bigint),ai_review_v4.renew_application_v4(uuid,uuid,uuid,bigint),ai_review_v4.defer_application_v4(uuid,uuid,uuid,bigint,text),ai_review_v4.prepare_application_v4(text,uuid,uuid,uuid,bigint,uuid,bigint,bytea,jsonb),ai_review_v4.publish_application_v4(text,uuid,uuid,uuid,bigint,uuid,uuid,bigint,bytea,bigint,bytea,bytea),governance_jobs_v4.prepare_ai_console_v4(text,uuid,uuid,uuid,bigint,bigint,timestamptz,uuid,bigint,bytea,jsonb),governance_jobs_v4.publish_ai_console_v4(text,uuid,uuid,uuid,bigint,bigint,timestamptz,uuid,uuid,bigint,bytea,bigint,bytea,bytea,jsonb,text,jsonb) TO __APP__;
RESET ROLE;
